    /// Scratch dir for `pick_sd_checkpoint` tests: unique per test (tests run
    /// in parallel), std-only, best-effort cleanup.
    fn sd_test_dir(name: &str) -> std::path::PathBuf {
        let dir = std::env::temp_dir()
            .join("wupi_sd_picker_tests")
            .join(format!("{}_{}", name, std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).expect("create sd picker test dir");
        dir
    }
    fn sd_test_file(dir: &std::path::Path, name: &str, size: usize) -> std::path::PathBuf {
        let p = dir.join(name);
        std::fs::write(&p, vec![0u8; size]).expect("write sd picker test file");
        p
    }

    #[test]
    fn pick_sd_checkpoint_prefers_gguf_layout_over_larger_safetensors() {
        // 2026-08-15: the assembled multi-file GGUF layout (gguf UNet + CLIP-G
        // sibling) is the path sd.cpp currently loads cleanly; the intended
        // final checkpoint (a LARGER single-file .safetensors whose sd.cpp
        // load is the next fix target) must not shadow it while both sit in
        // the dir for testing. The old size-only selector picked the
        // safetensors — silently bypassing the multi-file path entirely.
        let dir = sd_test_dir("prefers_gguf");
        sd_test_file(&dir, "image.gguf", 100);
        sd_test_file(&dir, "image.safetensors", 500);
        sd_test_file(&dir, "clip_l.safetensors", 50);
        sd_test_file(&dir, "clip_g.safetensors", 60);
        sd_test_file(&dir, "sdxl_vae_fp16_fix.safetensors", 40);
        let picked = pick_sd_checkpoint(&dir).expect("a checkpoint exists");
        assert_eq!(
            picked.file_name().and_then(|n| n.to_str()),
            Some("image.gguf"),
            "assembled GGUF layout must win over the larger safetensors"
        );
        // The HF diffusers CLIP-G convention (text_encoder_2) must count as
        // the CLIP-G sibling too — same needles as resolve_multi_file_layout.
        let dir2 = sd_test_dir("prefers_gguf_hf_names");
        sd_test_file(&dir2, "image.gguf", 100);
        sd_test_file(&dir2, "image.safetensors", 500);
        sd_test_file(&dir2, "text_encoder_2.safetensors", 60);
        let picked2 = pick_sd_checkpoint(&dir2).expect("a checkpoint exists");
        assert_eq!(
            picked2.file_name().and_then(|n| n.to_str()),
            Some("image.gguf"),
            "text_encoder_2 is the CLIP-G sibling (HF convention)"
        );
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::remove_dir_all(&dir2);
    }

    #[test]
    fn pick_sd_checkpoint_falls_back_to_largest_without_clip_g() {
        // Without a CLIP-G sibling there is no assembled multi-file layout —
        // the legacy largest-file selector applies (the single-file path with
        // runtime Q8_0). Also the contract for AFTER the safetensors loader
        // fix: with the test GGUF removed, image.safetensors picks itself.
        let dir = sd_test_dir("falls_back_largest");
        sd_test_file(&dir, "image.gguf", 100);
        sd_test_file(&dir, "image.safetensors", 500);
        sd_test_file(&dir, "clip_l.safetensors", 50);
        let picked = pick_sd_checkpoint(&dir).expect("a checkpoint exists");
        assert_eq!(
            picked.file_name().and_then(|n| n.to_str()),
            Some("image.safetensors"),
            "no CLIP-G sibling → largest file wins"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn pick_sd_checkpoint_gguf_only_dir() {
        // A lone GGUF (no siblings at all) falls through to the largest-file
        // rule and picks itself — the multi-file resolution then warns about
        // the missing CLIP-G at load time (version detection needs it).
        let dir = sd_test_dir("gguf_only");
        sd_test_file(&dir, "image.gguf", 100);
        let picked = pick_sd_checkpoint(&dir).expect("a checkpoint exists");
        assert_eq!(
            picked.file_name().and_then(|n| n.to_str()),
            Some("image.gguf")
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[tokio::test]
    async fn local_model_lock_serializes_consumers() {
        // The local-model turn lock (2026-08-08) guarantees at most ONE local
        // decode runs at any instant across chat / tracker / schema. Simulate
        // two concurrent consumers both holding the lock + a "currently
        // running" counter; assert it NEVER exceeds 1.
        let lock = Arc::new(tokio::sync::Mutex::new(()));
        let running = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let max_seen = Arc::new(std::sync::atomic::AtomicUsize::new(0));

        let mut handles = Vec::new();
        for _ in 0..2 {
            let (lock, running, max_seen) =
                (Arc::clone(&lock), Arc::clone(&running), Arc::clone(&max_seen));
            handles.push(tokio::spawn(async move {
                let _g = lock.lock().await;
                let cur = running.fetch_add(1, std::sync::atomic::Ordering::SeqCst) + 1;
                max_seen.fetch_max(cur, std::sync::atomic::Ordering::SeqCst);
                // Yield a few times so the other task gets a chance to race.
                for _ in 0..5 {
                    tokio::task::yield_now().await;
                }
                running.fetch_sub(1, std::sync::atomic::Ordering::SeqCst);
            }));
        }
        for h in handles {
            h.await.unwrap();
        }
        assert_eq!(
            max_seen.load(std::sync::atomic::Ordering::SeqCst),
            1,
            "local-model turn lock must serialize — at most ONE consumer at a time"
        );
    }

    // ── most_recent_continue_target (title CONTINUE resume target) ───────
    // Pins the CONTINUE contract: resume the freshest save for any New Game
    // world, autosaves included. Builds real save files via fable_save::write_save
    // so the test exercises the same on-disk layout the command reads.
    fn fake_card_for_continue(id: &str) -> sim_card::SimCard {
        // Mirrors fable_save.rs's fake_card() (SimCard has no Default derive).
        sim_card::SimCard {
            id: id.into(),
            name: id.into(),
            card_type: "simulation".into(),
            subtype: None,
            format_v2: false,
            identity: Default::default(),
            persona: Default::default(),
            world: Default::default(),
            location: None,
            inventory: Default::default(),
            properties: Vec::new(),
            linked_codices: Vec::new(),
            core_persona: String::new(),
            traits: String::new(),
            appearance: String::new(),
            role_instruction: String::new(),
            responsibilities: String::new(),
            conversational_rules: String::new(),
            technical_rules: String::new(),
            introductions: Vec::new(),
            intro: String::new(),
            intro_variants: Vec::new(),
            setting: Some("A test place.".into()),
            plot: None,
            player_name: Some("Tester".into()),
            custom_tags: Default::default(),
        }
    }

    /// Materialize the card folder + one session save in the 2026-08-22
    /// layout (`cards/<Card>/` + `data/saves/<Card>/<session>/saves/`) the
    /// Continue walker reads.
    fn seed_continue_save(
        root: &std::path::Path,
        card: &sim_card::SimCard,
        save_id: &str,
        name: &str,
    ) {
        std::fs::create_dir_all(root.join("cards").join(&card.id)).unwrap();
        fable_save::write_save(
            root, card, "session_1", save_id, name,
            &session::Conversation::new(), &schema::WorldSchema::default(), &[],
        ).unwrap();
    }

    // ── (2026-08-22 session decoupling) the dynamic-data boot migration ────
    // Pins: sessions (split JSONs + session.json + saves/) move into
    // data/saves/<CardName>/<session_id>/, the .codex sibling moves into the
    // universal library + is <linked_codices>-linked, and the whole thing is
    // IDEMPOTENT (a second run is a no-op).
    #[test]
    fn continue_target_picks_most_recent_save_across_worlds() {
        let tmp = tempfile::tempdir().unwrap();
        // Two New Game worlds, each with a save. The newer one (newer_world)
        // should win regardless of which card it came from.
        let older = fake_card_for_continue("older_world");
        let newer = fake_card_for_continue("newer_world");
        seed_continue_save(tmp.path(), &older, "save_a", "A");
        std::thread::sleep(std::time::Duration::from_millis(20));
        seed_continue_save(tmp.path(), &newer, "save_b", "B");

        let target = most_recent_continue_target(tmp.path()).expect("a target exists");
        assert_eq!(target.card_id, "newer_world");
        assert_eq!(target.save_id, "save_b");
        assert_eq!(target.session_id, "session_1", "the owning session rides the target");
    }

    #[test]
    fn continue_target_includes_autosaves() {
        // The freshest save is an autosave. CONTINUE must resume it (the per-
        // turn checkpoint), not skip it for an older manual save.
        let tmp = tempfile::tempdir().unwrap();
        let card = fake_card_for_continue("world_with_auto");
        seed_continue_save(tmp.path(), &card, "save_manual", "Manual");
        std::thread::sleep(std::time::Duration::from_millis(20));
        seed_continue_save(tmp.path(), &card, fable_save::AUTOSAVE_ID, "Autosave");

        let target = most_recent_continue_target(tmp.path()).expect("a target exists");
        assert_eq!(target.save_id, fable_save::AUTOSAVE_ID);
        assert!(target.is_autosave);
    }


    /// NEVER includes tool declarations. The narrator is creative prose +
    /// bracket commands, never structured tool calls. This test pins the
    /// structural exclusion so a future refactor that accidentally routes
    /// tools into the narrator path fails loudly.
    #[test]
    fn fable_send_never_includes_tools() {
        let prompt = build_narrator_prompt("You are the narrator.", &[]);
        // No tool declaration markers in the narrator prompt.
        assert!(
            !prompt.contains("<|tool>declaration:"),
            "narrator prompt must never include tool declarations: {prompt}"
        );
        // No tool_call / tool_response protocol tokens either.
        assert!(
            !prompt.contains("<|tool_call>"),
            "narrator prompt must never include tool_call markers: {prompt}"
        );
        assert!(
            !prompt.contains("<|tool_response>"),
            "narrator prompt must never include tool_response markers: {prompt}"
        );
    }

    /// §7 sibling (2026-07-29, amended 2026-08-16 retrieval diet + 2026-08-19
    /// cache-order ruling): the API NARRATOR system prompt is the STABLE CACHE
    /// PAYLOAD ONLY — authored narrator prose + the `<player>` block + the
    /// `<sim_card>` block. The memory block + `<world_state>` +
    /// `<scene_pacing>` NEVER ride the system message (they inject at depth 2
    /// + as the trailing system message in the Stage-2 assembly). The TRACKER
    /// builder still takes NO memory block AT ALL (structurally). Pin BOTH
    /// directions so a future refactor fails loudly either way.
    #[test]
    fn narrator_prompt_cache_order_blocks() {
        use crate::schema::{SceneMode, ScenePacing};
        use crate::sim_card::SimCard;

        let card = SimCard {
            id: "test".to_owned(),
            name: "Test Scenario".to_owned(),
            card_type: "simulation".to_owned(),
            subtype: Some("world".to_owned()),
            format_v2: true,
            identity: crate::sim_card::CardIdentity {
                gender: Some("Female".to_owned()),
                ..Default::default()
            },
            persona: crate::sim_card::CardPersona {
                personality: Some("Watchful.".to_owned()),
                ..Default::default()
            },
            world: crate::sim_card::CardWorld::default(),
            location: None,
            inventory: crate::sim_card::CardInventory::default(),
            properties: Vec::new(),
            linked_codices: Vec::new(),
            core_persona: String::new(),
            traits: String::new(),
            appearance: String::new(),
            role_instruction: String::new(),
            responsibilities: String::new(),
            conversational_rules: String::new(),
            technical_rules: String::new(),
            introductions: Vec::new(),
            intro: String::new(),
            intro_variants: Vec::new(),
            setting: Some("A test.".to_owned()),
            plot: None,
            player_name: Some("Kaelen".to_owned()),
            custom_tags: Default::default(),
        };
        let pacing = ScenePacing {
            mode: SceneMode::Exploration,
            spatial: 0,
            emotional: 0,
            kinetic: 0,
        };

        // Tracker path: NO memory block — the builder has no param for one
        // (compile-level enforcement), and the render must contain no
        // retrieved-knowledge tag even with retrieval live in the turn.
        let tracker_prompt = build_narrator_system_prompt(
            &prompts::FablePrompts::test_default(),
            &card,
            Some("gold: 100"),
            pacing,
            None,
            &[],
        );
        assert!(
            !tracker_prompt.contains("<retrieved_knowledge>"),
            "tracker prompt must NEVER render <retrieved_knowledge> (retrieval diet — \
             the schema is its memory; the block belongs to the 16k API narrator)"
        );
        assert!(
            !tracker_prompt.contains("<emit_errors>"),
            "an empty reject slot renders NO feedback block (zero echo on healthy turns)"
        );
        assert!(
            !tracker_prompt.contains("Bracket Commands Reference"),
            "tracker prompt must not carry retrieved codex content"
        );
        // The tracker's id sources survive: world_state + scene_pacing still render.
        assert!(tracker_prompt.contains("<world_state>"));
        assert!(tracker_prompt.contains("<scene_pacing"));

        // API narrator system message: authored prose → <player> →
        // <sim_card>, and NOTHING per-turn.
        let api_prompt = build_api_narrator_system_prompt(
            &prompts::FablePrompts::test_default(),
            &card,
            Some("<player>\nName: Kaelen\nGender: Male\n</player>"),
        );
        let narrator = prompts::FablePrompts::test_default().narrator.trim().to_string();
        if !narrator.is_empty() {
            let np = api_prompt.find(narrator.as_str()).expect("narrator prose");
            let pp = api_prompt.find("<player>").expect("player block");
            let cp = api_prompt.find("<sim_card>").expect("card block");
            assert!(np < pp, "narrator prose leads the system message");
            assert!(pp < cp, "the player block precedes the card block");
        }
        assert!(api_prompt.contains("Gender: Male"));
        assert!(api_prompt.contains("Name: Test Scenario"));
        assert!(api_prompt.contains("Personality: Watchful."));
        assert!(api_prompt.contains("Setting:\nA test."));
        // The mutable/world-state payload never rides the system message.
        assert!(
            !api_prompt.contains("<retrieved_knowledge>"),
            "memory injects at depth 2, never in the system message"
        );
        assert!(
            !api_prompt.contains("<world_state>"),
            "world_state rides the trailing message, never the system message"
        );
        assert!(!api_prompt.contains("<scene_pacing"));

        // The trailing turn tail: player_action → world_state → scene_pacing
        // (the old skeleton order, after the history now). ALWAYS non-empty
        // (scene_pacing renders every turn).
        let tail = build_narrator_turn_tail(Some("opened the chest"), Some("gold: 100"), pacing, None, None);
        let pa = tail.find("<player_action").expect("player_action");
        let ws = tail.find("<world_state>").expect("world_state tag");
        let sp = tail.find("<scene_pacing").expect("scene_pacing tag");
        assert!(pa < ws, "player_action leads the tail");
        assert!(ws < sp, "world_state precedes scene_pacing");
        assert!(!tail.contains("<retrieved_knowledge>"));
        // Even with no action + no world state, the pacing block renders.
        let bare = build_narrator_turn_tail(None, None, pacing, None, None);
        assert!(bare.contains("<scene_pacing"));
        assert!(!bare.contains("<world_state>"));
        // (2026-08-22 Ghost Writer) A guided direction renders LAST, under
        // every mechanical block.
        let guided = build_narrator_turn_tail(None, None, pacing, None, Some("<direction>\nX\n</direction>\n"));
        let sp2 = guided.find("<scene_pacing").expect("scene_pacing tag");
        let dir = guided.find("<direction>").expect("direction tag");
        assert!(sp2 < dir, "the player's direction is the last thing the narrator reads");
    }

    /// (2026-08-16 tracker-budget fix, P1.4; 2026-08-21 no-degrade rewrite)
    /// THE WORST-CASE BUDGET TEST.
    ///
    /// Renders the tracker prompt with EVERY variable component at its legal
    /// maximum and asserts the bounded FULL render fits — the regression pin
    /// for the recurring overflow → headless-prompt → zero-brackets failure
    /// mode. Any growth in the bracket list, the lean world-state caps, or
    /// the authored AGENT section trips this before it ships. Chars, not
    /// tokens (no tokenizer at the prompt layer); the budget constant is
    /// DERIVED from CTX_FABLE (8192 since the 2026-08-21 Chloe ruling) ×
    /// the 3.6 chars/token safety ratio vs the observed 3.7–4.0.
    ///
    /// (2026-08-21 Chloe ruling: NO degrade tier.) There is ONE tier — the
    /// full teaching + full lean world-state. The old core-tier pin (which
    /// accepted stripping the site/economy verbs on overflow) is RETIRED:
    /// Cinderfen lost its economy teaching for a whole session that way.
    /// Over-budget now means the loud skip — so this pin demands the MAXED
    /// world fits the FULL render, and additionally that the full site +
    /// economy verb teaching is PRESENT in it.
    #[test]
    fn tracker_prompt_worst_case_fits_char_budget() {
        use crate::schema::{SceneMode, ScenePacing};

        // The authored AGENT prose is the real fixed cost — load the real
        // data/fable.prompt when the test runs from the crate root (cargo
        // test cwd = src-tauri), else fall back to a synthetic section
        // GENEROUSLY larger than the real one so the pin still bites.
        let prompts = match std::path::Path::new("../data/fable.prompt").exists() {
            true => prompts::load_fable_prompts(std::path::Path::new("../data/fable.prompt")),
            false => prompts::FablePrompts {
                narrator: String::new(),
                agent: "agent ".repeat(800), // 4000 chars > real ~3400
            },
        };

        let schema = maxed_world_schema();
        let world_state = render_tracker_world_state(&schema);
        // (2026-08-21 evening "never truncate" ruling, pinned) The
        // count-cap composition — every list at its raised cap with
        // realistic-max prose — renders with ZERO ellipsis. The stages +
        // line-bound exist for degenerate prose compositions only; if this
        // assert fires, a cap outgrew stage 0's line budget: raise the
        // STAGE0 line cap (the prompt budget has the room) rather than
        // letting real play clip.
        assert!(
            !world_state.contains('…'),
            "the count-cap world-state must pass stage 0 un-clipped"
        );
        let pacing = ScenePacing {
            mode: SceneMode::Combat,
            spatial: 2,
            emotional: 2,
            kinetic: 2,
        };
        // Longest realistic action: a detailed typed action (the 4000-char
        // FABLE_ACTION_CHAR_CAP is a paste backstop — at 8192 even that
        // fits, but the pin uses the realistic design point).
        let action = "I ".to_owned() + &"advance through the burning market, sword up. ".repeat(14);
        let window = vec![
            tmsg(
                session::Role::Assistant,
                "n".repeat(crate::settings::TRACKER_ASSISTANT_CHAR_CAP),
            ),
            tmsg(session::Role::User, action.clone()),
        ];

        // PIN 1 — THE MAXED WORLD must fit the FULL render (no tier below
        // exists; overflow would mean the loud skip in production). The
        // emit_errors payload is the WORST-CASE block (max lines, max line
        // chars) so the pin counts its bounded cost honestly.
        let max_emit_errors = distill_tracker_emit_errors(
            &(0..settings::TRACKER_EMIT_ERROR_MAX_LINES + 4)
                .map(|i| {
                    let unique = format!("reject marker {i} — ");
                    unique + &"x".repeat(settings::TRACKER_EMIT_ERROR_LINE_CHARS + 40)
                })
                .collect::<Vec<String>>(),
        );
        assert_eq!(
            max_emit_errors.len(),
            settings::TRACKER_EMIT_ERROR_MAX_LINES,
            "the distill cap holds"
        );
        let full_system = build_narrator_system_prompt(
            &prompts,
            &fake_tracker_card(),
            Some(&world_state),
            pacing,
            None,
            &max_emit_errors,
        );
        let full_prompt = match build_tracker_prompt_bounded(
            &full_system,
            &window,
            settings::TRACKER_PROMPT_CHAR_BUDGET,
        ) {
            Ok(p) => p,
            Err(chars) => panic!(
                "MAXED-world tracker prompt over budget even after the tail-drop: \
                 {} chars > {}. There is NO degrade tier anymore (2026-08-21 Chloe \
                 ruling) — this would loud-skip every turn in production. Shrink the \
                 prompt per the Prime Directive or raise CTX_FABLE (Chloe's call).",
                chars,
                settings::TRACKER_PROMPT_CHAR_BUDGET
            ),
        };
        assert!(
            full_prompt.contains("<|turn>user"),
            "the user action must never be dropped"
        );
        // The full site + economy verb teaching rides even the maxed-world
        // render — the Cinderfen regression was exactly its silent loss.
        assert!(
            full_prompt.contains("[LEDGER found"),
            "the economy verb teaching must survive the maxed-world render"
        );
        assert!(
            full_prompt.contains("[ROOM"),
            "the site verb teaching must survive the maxed-world render"
        );
        assert!(
            full_prompt.contains("<emit_errors>"),
            "the reject-feedback block must survive the maxed-world render"
        );
        // (2026-08-22 living-world) The living-world surfaces ride the
        // maxed-world render too: the quest line + verb teaching, the
        // rested anchor, and the activated mana line.
        assert!(
            full_prompt.contains("quests:"),
            "the quest line must survive the maxed-world render"
        );
        assert!(
            full_prompt.contains("[QUEST new"),
            "the quest verb teaching must survive the maxed-world render"
        );
        // (2026-08-22 multihog WS1) The expiry verb teaching rides the
        // maxed-world render (the worst-case tracker-budget pin builds from
        // the real bracket list, so its bounded cost is counted honestly).
        assert!(
            full_prompt.contains("[EXPIRY"),
            "the expiry verb teaching must survive the maxed-world render"
        );
        // (2026-08-22 multihog WS2) The unlock verb teaching rides it too.
        assert!(
            full_prompt.contains("[UNLOCK"),
            "the unlock verb teaching must survive the maxed-world render"
        );
        assert!(
            full_prompt.contains("rested: 8h since last rest"),
            "the rested anchor line must survive the maxed-world render"
        );
        assert!(
            full_prompt.contains("mana: Strained"),
            "the activated arcane pool must survive the maxed-world render"
        );

        // PIN 2 — the realistic case: a Liam-shaped world state (real
        // playtest shape — one npc card, seeded wardrobe, no site map, no
        // economy) + a normal-length typed action fits the FULL render.
        let realistic_state = "date: March 15, 2026\nclock: 10:00 AM\nweather: Sunny\ntone: Comedy, Romance, Smut, Transformation, Feminization\nlocation: Liam's House, Los Angeles, California\ncast: liam\nplayer_state:\n  health: Excellent\n  stamina: Fresh\n  belt: Phone, Wallet\n  pack: Suitcase, Charger, Spare Clothes, Toiletry Kit, Snacks\n"
            .to_owned()
            + &"x".repeat(400); // headroom slop for richer real worlds
        let realistic_window = vec![
            tmsg(
                session::Role::Assistant,
                "Liam leans on the doorframe and grins. \"You made it! Come in, come in.\"".to_owned(),
            ),
            tmsg(
                session::Role::User,
                "I'd nervously reach my hand forward pressing the Ring doorbell.".to_owned(),
            ),
        ];
        let realistic_system = build_narrator_system_prompt(
            &prompts,
            &fake_tracker_card(),
            Some(&realistic_state),
            pacing,
            None,
            &[],
        );
        match build_tracker_prompt_bounded(
            &realistic_system,
            &realistic_window,
            settings::TRACKER_PROMPT_CHAR_BUDGET,
        ) {
            Ok(p) => {
                assert!(
                    p.chars().count() <= settings::TRACKER_PROMPT_CHAR_BUDGET,
                    "realistic-world tracker prompt {} chars > budget {}",
                    p.chars().count(),
                    settings::TRACKER_PROMPT_CHAR_BUDGET
                );
                assert!(p.contains("<|turn>user"), "the user action must never be dropped");
            }
            Err(chars) => panic!(
                "REALISTIC-world tracker prompt over budget even after the tail-drop: \
                 {} chars > {}. This is the exact 2026-08-21 Liam regression — shrink \
                 the prompt per the Prime Directive, never raise the context.",
                chars,
                settings::TRACKER_PROMPT_CHAR_BUDGET
            ),
        }
    }

    /// (2026-08-21 dialogue-loop guard) The verbatim-repeat detector: fires
    /// on ≥3 occurrences across ≥2 assistant messages (the GLM 5.2
    /// consent-tease loop from the 2026-08-21 playtest), normalizes
    /// case/punctuation, ignores short spans + twice-said refrains.
    #[test]
    fn detect_repeated_dialogue_fires_on_cross_turn_loops() {
        let beat = |q: &str| {
            tmsg(
                session::Role::Assistant,
                format!("He breathes out. {q} He steps closer."),
            )
        };
        let window = vec![
            tmsg(session::Role::User, "I stand still.".to_owned()),
            beat("\"You should stop me. But please don't.\""),
            tmsg(session::Role::User, "I hesitate.".to_owned()),
            beat("\"you should stop me.. but please don't\""),
            tmsg(session::Role::User, "I nod.".to_owned()),
            beat("\"You should stop me! But please don't?\""),
        ];
        let (line, n) = detect_repeated_dialogue(&window).expect("the loop must fire");
        assert_eq!(n, 3, "three verbatim-normalized occurrences");
        assert!(line.to_lowercase().contains("stop me"));

        // A twice-said refrain is legitimate — no fire.
        let window2 = vec![
            beat("\"We're so close now.\""),
            tmsg(session::Role::User, "mm".to_owned()),
            beat("\"we're so close now\""),
        ];
        assert!(detect_repeated_dialogue(&window2).is_none());

        // Short spans never fire ("Okay." ×3 is a tic, not a loop).
        let window3 = vec![
            beat("\"Okay.\""),
            tmsg(session::Role::User, "hm".to_owned()),
            beat("\"okay\""),
            tmsg(session::Role::User, "hm".to_owned()),
            beat("\"Okay!\""),
        ];
        assert!(detect_repeated_dialogue(&window3).is_none());

        // Three occurrences but all in ONE message = beat-internal
        // repetition (the within-stream detector's domain), not cross-turn.
        let window4 = vec![tmsg(
            session::Role::Assistant,
            "He says \"stop me already, okay?\" then \"stop me already, okay?\" then \"Stop me already, okay?\"".to_owned(),
        )];
        assert!(detect_repeated_dialogue(&window4).is_none());
    }

    /// (2026-08-21 narration-loop guard) The verbatim narration sibling:
    /// fires on the "smirk and sigh" tell repeated ≥3× across ≥2 assistant
    /// beats (normalized case/punctuation-insensitive), ignores quoted
    /// dialogue (the other detector's domain), twice-said motifs, grams
    /// under the char floor, user text, and beat-internal repetition.
    #[test]
    fn detect_repeated_narration_fires_on_cross_tell_loops() {
        let window = vec![
            tmsg(session::Role::User, "I wait.".to_owned()),
            tmsg(
                session::Role::Assistant,
                "He breathes out. She shifts her weight, smirking. The fire pops.".to_owned(),
            ),
            tmsg(session::Role::User, "I speak.".to_owned()),
            tmsg(
                session::Role::Assistant,
                "He steps closer. she shifts her WEIGHT... smirking A shutter bangs.".to_owned(),
            ),
            tmsg(session::Role::User, "I leave.".to_owned()),
            tmsg(
                session::Role::Assistant,
                "He looks away. She shifts her weight; smirking. The candle gutters.".to_owned(),
            ),
        ];
        let (gram, n) = detect_repeated_narration(&window).expect("the tell loop must fire");
        assert_eq!(n, 3, "three verbatim-normalized occurrences");
        // Both tied winning grams ("she shifts her weight" /
        // "shifts her weight smirking") carry the tell — the assertion is
        // tie-safe by construction.
        assert!(gram.contains("shifts her weight"), "got {gram:?}");

        // Quoted dialogue never reaches the narration detector —
        // strip_dialogue removes the span before tokenizing (and the
        // surrounding narration varies per beat).
        let window2 = vec![
            tmsg(
                session::Role::Assistant,
                "He leans in. \"Stop me already.\" The fire pops.".to_owned(),
            ),
            tmsg(session::Role::User, "hm".to_owned()),
            tmsg(
                session::Role::Assistant,
                "He steps back. \"stop me already\" The door creaks.".to_owned(),
            ),
            tmsg(session::Role::User, "hm".to_owned()),
            tmsg(
                session::Role::Assistant,
                "He looks away. \"Stop me already.\" A log settles.".to_owned(),
            ),
        ];
        assert!(
            detect_repeated_narration(&window2).is_none(),
            "dialogue spans are stripped before tokenizing — quoted loops are the dialogue detector's domain"
        );

        // A twice-said tell is a motif, not a loop.
        let window3 = vec![
            tmsg(
                session::Role::Assistant,
                "He waits. She shifts her weight, smirking.".to_owned(),
            ),
            tmsg(session::Role::User, "hm".to_owned()),
            tmsg(
                session::Role::Assistant,
                "He waits more. She shifts her weight, smirking.".to_owned(),
            ),
        ];
        assert!(detect_repeated_narration(&window3).is_none());

        // Short grams stay under the floor ("he looks at me" = 14 chars — a
        // glance tic ×3 is legal; only ≥15-char grams fire).
        let window4 = vec![
            tmsg(
                session::Role::Assistant,
                "The wind rises. He looks at me. I hold still.".to_owned(),
            ),
            tmsg(session::Role::User, "hm".to_owned()),
            tmsg(
                session::Role::Assistant,
                "A shutter bangs. He looks at me. My throat tightens.".to_owned(),
            ),
            tmsg(session::Role::User, "hm".to_owned()),
            tmsg(
                session::Role::Assistant,
                "The fire pops. He looks at me. My hands stay down.".to_owned(),
            ),
        ];
        assert!(detect_repeated_narration(&window4).is_none());

        // User-message text is never scanned.
        let window5 = vec![
            tmsg(
                session::Role::User,
                "She shifts her weight, smirking. She shifts her weight, smirking. She shifts her weight, smirking.".to_owned(),
            ),
            tmsg(session::Role::Assistant, "He watches.".to_owned()),
        ];
        assert!(detect_repeated_narration(&window5).is_none());

        // Three occurrences but all in ONE message = beat-internal
        // repetition (the within-stream detector's domain).
        let window6 = vec![tmsg(
            session::Role::Assistant,
            "She shifts her weight, smirking. She shifts her weight, smirking. She shifts her weight, smirking.".to_owned(),
        )];
        assert!(detect_repeated_narration(&window6).is_none());
    }

    /// P1.4 sibling: the tail-drop re-render — an over-budget window loses
    /// the preceding assistant beat (lowest-priority tail block) and keeps
    /// the trailing user action; an unfixable prompt (system alone over
    /// budget) errs for the caller to fail loudly on.
    #[test]
    fn tracker_prompt_bounded_tail_drop_and_err() {
        // Tail-drop: system ~5.6k chars + beat 600 + action ~3.9k → over the
        // 9800 budget; dropping the beat recovers it.
        let system = "s".repeat(5_600);
        let window = vec![
            tmsg(
                session::Role::Assistant,
                "ASSISTANT-BEAT-MARKER ".repeat(28), // ~600 chars
            ),
            tmsg(session::Role::User, "u".repeat(3_900)),
        ];
        let full = build_narrator_prompt(&system, &window);
        assert!(full.chars().count() > settings::TRACKER_PROMPT_CHAR_BUDGET);
        let bounded = build_tracker_prompt_bounded(
            &system,
            &window,
            settings::TRACKER_PROMPT_CHAR_BUDGET,
        )
        .expect("tail-drop must recover");
        assert!(bounded.chars().count() <= settings::TRACKER_PROMPT_CHAR_BUDGET);
        assert!(
            !bounded.contains("ASSISTANT-BEAT-MARKER"),
            "the preceding assistant beat is the lowest-priority tail block — dropped first"
        );
        assert!(bounded.contains(&"u".repeat(100)), "the user action survives");

        // Unfixable: the system prompt ALONE busts the budget → Err (the
        // caller skips the tracker pass loudly instead of decoding headless).
        let fat_system = "s".repeat(settings::TRACKER_PROMPT_CHAR_BUDGET + 1);
        assert!(
            build_tracker_prompt_bounded(&fat_system, &window, settings::TRACKER_PROMPT_CHAR_BUDGET)
                .is_err()
        );
        // (2026-08-22) The re-track budget is TIGHTER than the live budget
        // (its generation wall is double) — a render sized to fit the LIVE
        // budget untouched must still tail-drop under the re-track budget,
        // never decode against a 512-token reserve it overruns.
        let mid_system =
            "s".repeat(settings::TRACKER_RETRACK_PROMPT_CHAR_BUDGET - 4_000);
        let live_ok = build_tracker_prompt_bounded(
            &mid_system,
            &window,
            settings::TRACKER_PROMPT_CHAR_BUDGET,
        )
        .expect("fits the live budget untouched");
        assert!(
            live_ok.contains("ASSISTANT-BEAT-MARKER"),
            "no tail-drop is needed under the live budget"
        );
        let retrack = build_tracker_prompt_bounded(
            &mid_system,
            &window,
            settings::TRACKER_RETRACK_PROMPT_CHAR_BUDGET,
        )
        .expect("the re-track tail-drop recovers where the live budget never fired");
        assert!(
            retrack.chars().count() <= settings::TRACKER_RETRACK_PROMPT_CHAR_BUDGET
        );
        assert!(
            !retrack.contains("ASSISTANT-BEAT-MARKER"),
            "the tighter re-track budget drops the beat first"
        );
        assert!(retrack.contains(&"u".repeat(100)), "the user action survives");
    }

    /// P1.4 sibling: the lean tracker world-state render — injury prose is
    /// narrator material (dropped), and the count-cap composition passes
    /// stage 0 UN-CLIPPED (2026-08-21 evening ruling: the tracker never
    /// truncates real play; the bounds below are asserted against STAGE0's
    /// maxima since later stages only tighten).
    #[test]
    fn lean_tracker_world_state_caps_and_drops() {
        let schema = maxed_world_schema();
        let lean = render_tracker_world_state(&schema);
        let rich = render_fable_world_state(&schema, &[], false, false);

        // (2026-08-21 evening follow-up) The lean render is a near
        // PASSTHROUGH at the raised caps — the RATIO assert of the
        // cap-6/9k era is retired. What separates lean from rich is
        // exactly the referee-owned injury prose + the narrator's site
        // prose block (swapped for the compact id slice); the lean stays
        // strictly smaller on those.
        assert!(lean.chars().count() < rich.chars().count(),
            "the lean render stays strictly smaller (lean {} vs rich {})",
            lean.chars().count(), rich.chars().count());
        assert!(!lean.contains("injuries:"), "referee-owned injury prose is dropped for the tracker");
        assert!(rich.contains("injuries:"), "the narrator's rich render KEEPS injuries");
        // The id anchors survive verbatim — the bracket whitelist.
        assert!(lean.contains("cast:"));
        assert!(lean.contains("location:"));
        // (2026-08-21 evening) The count-cap composition renders with ZERO
        // ellipsis — "never truncate" pinned. STAGE 1+ fires only on
        // degenerate prose compositions, never on a maxed real world.
        assert!(!lean.contains('…'),
            "the maxed count-cap world-state must pass stage 0 un-clipped: {lean}");
        // The minds: cap MATCHES the presence cap — every on-camera NPC's
        // interior renders, the 16th included; exactly-at-cap produces NO
        // overflow marker.
        assert!(rich.contains("minds:"), "the rich render carries the interior line");
        assert!(
            lean.lines().any(|l| l.starts_with("minds: ") && l.contains("Character 15")),
            "the cap-th present NPC's interior renders (cap == presence cap)"
        );
        let minds_len = lean
            .lines()
            .find(|l| l.starts_with("minds: "))
            .map(|l| l.chars().count())
            .unwrap_or(0);
        assert!(minds_len > 0 && minds_len <= STAGE0.minds + 40,
            "minds line capped in the lean render (STAGE0 max; stages only tighten), got {minds_len}");
        // Newest events always survive; the oldest drops only under the
        // pressure stages (the composed maxed render lands past stage 0).
        assert!(lean.contains("event-newest"), "newest event survives");
        // (2026-08-21 evening) Stage 0 passes ALL SIX events — drive the
        // surgery directly so the pin is stage-deterministic.
        let stage0 = lean_world_state_surgery(&rich, &STAGE0);
        assert!(stage0.contains("event-oldest"), "stage 0 shows all six events (8192 ruling)");
        assert!(stage0.contains("event-newest"), "stage 0 shows the newest event");
        // The summary line is capped.
        let summary_len = lean
            .lines()
            .find(|l| l.starts_with("summary: "))
            .map(|l| l.chars().count())
            .unwrap_or(0);
        assert!(summary_len <= STAGE0.summary + 40, "summary capped in the lean render (STAGE0 max), got {summary_len}");
    }

    /// (2026-08-22 multihog WS2) The GM hidden-contents block: rides the
    /// NARRATOR world-state render (the `gm_hidden` flag), never the
    /// tracker's (hidden truth reaching the E4B would leak straight into
    /// its brackets); bounded at the entity cap; strictly 1-hop.
    #[test]
    fn gm_hidden_block_rides_narrator_render_only() {
        use crate::site_map::{
            AreaKnowledge, AssetKind, AssetKnowledge, AssetState, ConnState, SiteArea, SiteAsset,
            SiteConnection, SiteMap, SiteThreat,
        };
        let mut s = schema::WorldSchema::default();
        s.summary = "the scene is set".to_string();
        s.world_clock.current_minutes = 1_000;
        let area = |id: &str, k: AreaKnowledge, conns: Vec<SiteConnection>| SiteArea {
            id: id.to_owned(),
            name: id.to_owned(),
            knowledge: k,
            geometry: vec![],
            connections: conns,
        };
        let conn = |to: &str, st: ConnState| SiteConnection {
            to: to.to_owned(),
            state: st,
            detail: String::new(),
        };
        let asset = |id: &str, loc: &str, k: AssetKnowledge| SiteAsset {
            id: id.to_owned(),
            name: id.to_owned(),
            kind: AssetKind::Creature,
            location: loc.to_owned(),
            state: AssetState::Active,
            knowledge: k,
            count: 0,
            detail: String::new(),
            tier: None,
            ..Default::default()
        };
        let mut map = SiteMap {
            node_id: "warren".to_owned(),
            threat: SiteThreat::High,
            entrance: "gatehouse".to_owned(),
            current_area: Some("gatehouse".to_owned()),
            last_visit_minutes: 1_000,
            ..Default::default()
        };
        map.areas = vec![
            area("gatehouse", AreaKnowledge::Visited, vec![conn("hall", ConnState::Open)]),
            area("hall", AreaKnowledge::Unrevealed, vec![
                conn("gatehouse", ConnState::Open),
                conn("vault", ConnState::Locked),
            ]),
            area("vault", AreaKnowledge::Unrevealed, vec![conn("hall", ConnState::Locked)]),
        ];
        map.assets = vec![
            asset("hall-stalker", "hall", AssetKnowledge::Unrevealed),
            asset("vault-horror", "vault", AssetKnowledge::Unrevealed),
        ];
        s.site_maps.insert("warren".to_owned(), map);
        s.travel_graph.nodes = vec![schema::Node {
            id: "warren".to_owned(),
            name: "The Warren".to_owned(),
            ..Default::default()
        }];
        s.travel_graph.current_node = Some("warren".to_owned());

        // Narrator render: the block rides, right after the site slice.
        let narrator = render_fable_world_state(&s, &[], false, true);
        assert!(narrator.contains("<hidden_truth>"), "the block rides: {narrator}");
        assert!(narrator.contains("hall-stalker"), "the 1-hop hidden truth rides");
        assert!(
            !narrator.contains("vault-horror"),
            "2-hop truth stays out (locked door included): {narrator}"
        );
        // The block sits directly after the site block's last indented line.
        let site_pos = narrator.find("site:").expect("site slice present");
        let gm_pos = narrator.find("<hidden_truth>").expect("gm block");
        let present_pos = narrator.find("present:").unwrap_or(narrator.len());
        assert!(
            site_pos < gm_pos && gm_pos < present_pos,
            "the block follows the site slice"
        );

        // Tracker render: the block NEVER rides (the leak gate).
        let tracker = render_tracker_world_state(&s);
        assert!(!tracker.contains("<hidden_truth>"), "hidden truth never reaches the tracker");
        assert!(!tracker.contains("hall-stalker"));

        // Flag off (the aids' render): absent too.
        let aids = render_fable_world_state(&s, &[], false, false);
        assert!(!aids.contains("<hidden_truth>"));
    }

    /// (2026-08-18 audit; bounds updated 2026-08-21 morning + evening)
    /// STAGE2's `minds:` cut drops TRAILING entries at `, ` boundaries —
    /// with the importance-ranked render the casualties are ambient NPCs:
    /// the core principal leads the line and survives (at worst the tail of
    /// their entry clips; the character never drops out), while the deepest
    /// ambient entries fall off entirely. (Cap 180→500→800 across the 8192
    /// rulings — STAGE2 now holds the core principal + the leading
    /// ambients; the tail-most ambients still take the cut.)
    #[test]
    fn lean_minds_truncation_keeps_core_entries() {
        use crate::schema::{
            NpcEntry, NpcInterior, NpcProminence, NpcRegistry, Presence, PRESENCE_GRACE_RESET,
        };

        let mut s = schema::WorldSchema::default();
        let mut entries: Vec<NpcEntry> = (0..7)
            .map(|i| NpcEntry {
                id: format!("amb{i}"),
                name: format!("Amb{i}"),
                role: String::new(),
                tier: None,
                aliases: vec![],
                prominence: NpcProminence::Named,
            })
            .collect();
        entries.push(NpcEntry {
            id: "corekeep".into(),
            name: "Corekeep".into(),
            role: String::new(),
            tier: None,
            aliases: vec![],
            prominence: NpcProminence::Core,
        });
        s.npc_registry = NpcRegistry { entries };
        let mut presences: Vec<Presence> = (0..7)
            .map(|i| Presence {
                npc_id: format!("amb{i}"),
                name: format!("Amb{i}"),
                stance: String::new(),
                ttl: PRESENCE_GRACE_RESET,
            })
            .collect();
        presences.push(Presence {
            npc_id: "corekeep".into(),
            name: "Corekeep".into(),
            stance: String::new(),
            ttl: PRESENCE_GRACE_RESET,
        });
        s.presences = presences;
        // Maxed intents: every entry renders near the 200-char entry cap,
        // so STAGE2's 800-char line budget holds only the leading entries.
        for id in [
            "amb0", "amb1", "amb2", "amb3", "amb4", "amb5", "amb6", "corekeep",
        ] {
            s.npc_interior.insert(
                id.into(),
                NpcInterior {
                    intent: Some("i".repeat(160)),
                    ..NpcInterior::default()
                },
            );
        }
        let rich = render_fable_world_state(&s, &[], false, false);
        let stage2 = lean_world_state_surgery(&rich, &STAGE2);
        let minds = stage2
            .lines()
            .find(|l| l.starts_with("minds: "))
            .expect("minds line survives stage 2");
        assert!(
            minds.contains("Corekeep"),
            "the core principal leads and survives: {minds}"
        );
        assert!(!minds.contains("Amb6"), "the tail-most ambient entries take the cut: {minds}");
        assert!(
            minds.chars().count() <= 800 + 40,
            "stage-2 minds cap holds: {minds}"
        );
    }

    /// (2026-08-19 Hidden site maps) The tracker path swaps the rich
    /// multi-line `site:` block for the compact id-bearing slice — the
    /// tracker gets DOOR TARGET IDS (how an unrevealed room is entered),
    /// never the narrator prose, and the lean surgery caps it as one line.
    #[test]
    fn tracker_render_swaps_site_block_for_compact_ids() {
        let mut s = schema::WorldSchema::default();
        s.world_clock.current_minutes = 1_000;
        let mut map = site_map::SiteMap::default();
        map.node_id = "warren".into();
        map.entrance = "gatehouse".into();
        map.areas = vec![
            site_map::SiteArea {
                id: "gatehouse".into(),
                name: "Gatehouse".into(),
                knowledge: site_map::AreaKnowledge::Visited,
                geometry: vec!["cold draft through murder holes".into()],
                connections: vec![site_map::SiteConnection {
                    to: "hall".into(),
                    state: site_map::ConnState::Locked,
                    detail: "iron-bound door".into(),
                }],
            },
            site_map::SiteArea { id: "hall".into(), name: "Great Hall".into(), ..Default::default() },
            site_map::SiteArea { id: "vault".into(), name: "Vault".into(), ..Default::default() },
        ];
        s.site_maps.insert("warren".into(), map);
        s.travel_graph.current_node = Some("warren".into());

        let lean = render_tracker_world_state(&s);
        // The tracker slice: one flattened line with ids + door states.
        assert!(
            lean.contains("gatehouse:v doors=hall:locked"),
            "compact id slice missing: {lean}"
        );
        // The narrator prose does NOT survive the swap.
        assert!(!lean.contains("cold draft"), "narrator geometry must be swapped out");
        assert!(!lean.contains("threat:"), "narrator threat line must be swapped out");
        // No multi-line site block remains (one capped line).
        assert!(!lean.contains("site:\n"), "site block must be single-line");

        // The RICH render (narrator path) keeps the prose + hides truth.
        let rich = render_fable_world_state(&s, &[], false, false);
        assert!(rich.contains("site:\n"), "rich render keeps the block");
        assert!(rich.contains("cold draft"), "rich render keeps geometry");
        assert!(!rich.contains("Great Hall"), "unrevealed area stays hidden");
    }

    /// (2026-08-19) The lean surgery's site-block arm: the rich multi-line
    /// block (when driven directly, pre-swap) flattens to one capped line.
    #[test]
    fn lean_surgery_flattens_site_block_to_one_line() {
        let rich = "location: Warren (exits: town)\nsite:\n  threat: high; entrance: Gatehouse\n  Gatehouse (gatehouse) — visited: cold draft\n  ways on: Town\ncast: mara";
        let lean = lean_world_state_surgery(rich, &STAGE0);
        let site_lines = lean.lines().filter(|l| l.starts_with("site: ")).count();
        assert_eq!(site_lines, 1, "one flattened site line: {lean}");
        assert!(lean.contains("threat: high"), "content survives the flatten");
        assert!(!lean.contains("\n  threat"), "no indented continuations remain");
        assert!(lean.contains("cast: mara"), "following lines survive");
    }

